// Estado deseado y estado real de tres servidores (inventados).
const deseado = { puerto: 8080, trabajadores: 4, nivel_log: "info" };
const real = {
  s1: { puerto: 8080, trabajadores: 4, nivel_log: "info" },
  s2: { puerto: 8080, trabajadores: 16, nivel_log: "info" },
  s3: { puerto: 8081, trabajadores: 4, nivel_log: "debug" },
};
function aplicar(nombre, estado) {
  let cambios = 0;
  for (const [clave, valor] of Object.entries(deseado)) {
    if (estado[clave] !== valor) {
      console.log(`  ${nombre}: ${clave} ${estado[clave]} -> ${valor}`);
      estado[clave] = valor;
      cambios++;
    }
  }
  return cambios;
}
for (const pasada of [1, 2]) {
  console.log(`Pasada ${pasada}`);
  let total = 0;
  for (const [n, e] of Object.entries(real)) total += aplicar(n, e);
  console.log(`  cambios: ${total}`);
}
